Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>focal length f (K) <span id="fVal">1.50</span>
  <input type="range" id="focalLength" min="0.8" max="2.4" step="0.05" value="1.5"></label>
<label>camera yaw (R) <span id="yawVal">0.00</span>
  <input type="range" id="camYaw" min="-0.35" max="0.35" step="0.01" value="0"></label>
<label>camera translation tx (T) <span id="txVal">0.00</span>
  <input type="range" id="camTransX" min="-1.5" max="1.5" step="0.05" value="0"></label>
<div style="display:flex;gap:4px;">
  <button id="modeInd" class="active">Individual residuals</button>
  <button id="modeTot">Total sum-of-squares</button>
</div>
<div id="ssePanel" style="display:none;font-weight:bold;padding:4px;border:1px solid #c00;border-radius:4px;background:#fff5f5;"></div>
<div style="font-weight:bold;margin-top:4px;">Demo steps:</div>
<div style="display:flex;flex-wrap:wrap;gap:3px;">
  <button class="stepBtn" data-step="0">1: Small error</button>
  <button class="stepBtn" data-step="1">2: Wrong f</button>
  <button class="stepBtn" data-step="2">3: Wrong pose</button>
  <button class="stepBtn" data-step="3">4: Objective</button>
</div>
<div id="stepNarration" style="font-size:10px;max-width:180px;white-space:normal;color:#333;"></div>
<div style="font-size:10px;color:#555;max-width:180px;white-space:normal;">Drag any image point p<sub>i</sub> or p&prime;<sub>i</sub> on the plane to see the 2D residual change.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// camera tripod at origin → 3 ArrowHelpers green; labels X_L,Y_L,Z_L
// image plane → Rectangle wireframe (Edges of PlaneGeometry 2.2x3) at z=1.5, black
// world points P1,P2,P3 → SphereGeometry(0.15) red/cyan/green
// world triangle → BufferGeometry mesh orange + 3 edge cylinders near-black
// rays → 2 dashed lines each (grey origin→p, black p→P), LineDashedMaterial
// observed p_i → SphereGeometry(0.07) on plane z=1.5, matching colors
// image triangle → mesh orange + dark edge cylinders
// reprojected p'_i → SphereGeometry(0.07) darker outline, matching colors
// residuals → red cylinders radius 0.03 between p_i and p'_i
// mini tripod at image-triangle centroid → 3 small green arrows
const F_TRUE = 1.5, PX = 200;
const Pw = [
  new THREE.Vector3(4.5, 3.5, 9),    // P1 red
  new THREE.Vector3(3.2, -1.2, 8.5), // P2 cyan
  new THREE.Vector3(0.4, 2.8, 8)     // P3 green
];
const COLS = [0xee2211, 0x33bbee, 0x22dd22];
const NAMES = ['1', '2', '3'];
const state = { f: 1.5, yaw: 0, tx: 0, mode: 'ind' };

// ---- camera tripod at origin ----
function arrow(dir, len, color, headL = 0.12, headW = 0.07) {
  return new THREE.ArrowHelper(dir.clone().normalize(), new THREE.Vector3(), len, color, headL, headW);
}
scene.add(arrow(new THREE.Vector3(-1, 0, 0), 0.9, 0x22cc22));
scene.add(arrow(new THREE.Vector3(0, 1, 0), 0.9, 0x22cc22));
scene.add(arrow(new THREE.Vector3(0, 0, 1), 0.9, 0x22cc22));

// ---- image plane wireframe ----
const planeW = 2.2, planeH = 3;
const planeGeom = new THREE.PlaneGeometry(planeW, planeH);
const planeEdges = new THREE.LineSegments(new THREE.EdgesGeometry(planeGeom),
  new THREE.LineBasicMaterial({ color: 0x111111 }));
planeEdges.position.z = F_TRUE;
scene.add(planeEdges);

// ---- world points ----
const worldSpheres = Pw.map((p, i) => {
  const s = new THREE.Mesh(new THREE.SphereGeometry(0.16, 24, 16),
    new THREE.MeshBasicMaterial({ color: COLS[i] }));
  s.position.copy(p);
  scene.add(s);
  const ring = new THREE.Mesh(new THREE.SphereGeometry(0.165, 24, 16),
    new THREE.MeshBasicMaterial({ color: 0x111111, side: THREE.BackSide }));
  s.add(ring); ring.scale.setScalar(1.06);
  return s;
});

// ---- world triangle (orange fill + dark border cylinders) ----
function triMesh(a, b, c, color, opacity) {
  const g = new THREE.BufferGeometry().setFromPoints([a, b, c]);
  g.setIndex([0, 1, 2]);
  g.computeVertexNormals();
  return new THREE.Mesh(g, new THREE.MeshBasicMaterial({
    color, side: THREE.DoubleSide, transparent: true, opacity
  }));
}
scene.add(triMesh(Pw[0], Pw[1], Pw[2], 0xffaa22, 0.9));

const _up = new THREE.Vector3(0, 1, 0);
function edgeCyl(a, b, r, color) {
  const c = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 1, 10),
    new THREE.MeshBasicMaterial({ color }));
  setCyl(c, a, b);
  scene.add(c);
  return c;
}
function setCyl(c, a, b) {
  const d = new THREE.Vector3().subVectors(b, a);
  const len = d.length();
  c.position.copy(a).addScaledVector(d, 0.5);
  c.scale.set(1, Math.max(len, 1e-6), 1);
  c.quaternion.setFromUnitVectors(_up, d.normalize());
}
for (let i = 0; i < 3; i++) edgeCyl(Pw[i], Pw[(i + 1) % 3], 0.025, 0x1a1a1a);

// ---- observed points p_i (true projection) ----
function project(pt, f) { return new THREE.Vector3(f * pt.x / pt.z, f * pt.y / pt.z, F_TRUE); }
const pObs = Pw.map(p => project(p, F_TRUE));

function smallSphere(color, r = 0.07) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(r, 20, 14),
    new THREE.MeshBasicMaterial({ color }));
  const ring = new THREE.Mesh(new THREE.SphereGeometry(r * 1.12, 20, 14),
    new THREE.MeshBasicMaterial({ color: 0x111111, side: THREE.BackSide }));
  s.add(ring);
  scene.add(s);
  return s;
}
const obsSpheres = pObs.map((p, i) => { const s = smallSphere(COLS[i]); s.position.copy(p); return s; });

// ---- dashed rays: grey origin→p, black p→P ----
function dashedLine(color) {
  const l = new THREE.Line(new THREE.BufferGeometry(),
    new THREE.LineDashedMaterial({ color, dashSize: 0.16, gapSize: 0.12 }));
  scene.add(l);
  return l;
}
const rayGrey = pObs.map(() => dashedLine(0x999999));
const rayBlack = pObs.map(() => dashedLine(0x111111));
function setDashed(line, a, b) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints([a, b]);
  line.computeLineDistances();
}
const ORIGIN = new THREE.Vector3();
function updateRays() {
  for (let i = 0; i < 3; i++) {
    const p = obsSpheres[i].position;
    setDashed(rayGrey[i], ORIGIN, p);
    setDashed(rayBlack[i], p, Pw[i]);
  }
}

// ---- image triangle (fill + border) ----
const imgTriGeom = new THREE.BufferGeometry();
imgTriGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3));
imgTriGeom.setIndex([0, 1, 2]);
const imgTri = new THREE.Mesh(imgTriGeom, new THREE.MeshBasicMaterial({
  color: 0xffaa22, side: THREE.DoubleSide, transparent: true, opacity: 0.95
}));
scene.add(imgTri);
const imgEdges = [edgeCyl(pObs[0], pObs[1], 0.018, 0x1a1a1a),
                  edgeCyl(pObs[1], pObs[2], 0.018, 0x1a1a1a),
                  edgeCyl(pObs[2], pObs[0], 0.018, 0x1a1a1a)];

// ---- reprojected points p'_i ----
const repSpheres = pObs.map((p, i) => { const s = smallSphere(COLS[i], 0.065); s.position.copy(p); return s; });

// ---- residual cylinders (red, thick) ----
const resCyls = pObs.map((p, i) => edgeCyl(p, p, 0.03, 0xdd0000));

// ---- mini green tripod at image-triangle centroid ----
const miniTri = new THREE.Group();
miniTri.add(arrow(new THREE.Vector3(1, 0, 0), 0.28, 0x22cc22, 0.07, 0.05));
miniTri.add(arrow(new THREE.Vector3(0, 1, 0), 0.28, 0x22cc22, 0.07, 0.05));
miniTri.add(arrow(new THREE.Vector3(0.6, 0.35, 0.4), 0.28, 0x22cc22, 0.07, 0.05));
scene.add(miniTri);

// ---- reprojection model: yaw about Y, +tx on X, project with estimated f ----
function reproject(pt) {
  const c = Math.cos(state.yaw), s = Math.sin(state.yaw);
  const x = pt.x * c + pt.z * s + state.tx;
  const z = -pt.x * s + pt.z * c;
  return new THREE.Vector3(state.f * x / z, state.f * pt.y / z, F_TRUE);
}

// ---- labels ----
addLabel('<i><b>P</b></i><sub>1</sub>', Pw[0], { offset: [26, -14], fontSize: '16px' });
addLabel('<i><b>P</b></i><sub>2</sub>', Pw[1], { offset: [24, 14], fontSize: '16px' });
addLabel('<i><b>P</b></i><sub>3</sub>', Pw[2], { offset: [-24, -14], fontSize: '16px' });
addLabel('<i>X</i><sub>L</sub>', new THREE.Vector3(-1.0, 0, 0), { offset: [-8, 10] });
addLabel('<i>Y</i><sub>L</sub>', new THREE.Vector3(0, 1.0, 0), { offset: [-10, -8] });
addLabel('<i>Z</i><sub>L</sub>', new THREE.Vector3(0, 0, 1.0), { offset: [12, 12] });
const obsLabels = pObs.map((p, i) =>
  addLabel(`<i><b>p</b></i><sub>${NAMES[i]}</sub>`, p, { offset: [16, 14], fontSize: '15px' }));
const repLabels = pObs.map((p, i) =>
  addLabel(`<i><b>p</b></i>&prime;<sub>${NAMES[i]}</sub>`, p, { offset: [16, -14], fontSize: '14px' }));
const resLabels = pObs.map(p => addLabel('', p, { offset: [0, -16], fontSize: '11px', color: '#cc0000', background: 'rgba(255,255,255,0.8)' }));

// ---- reactive update ----
const ssePanel = document.getElementById('ssePanel');
function updateAll() {
  let sse = 0;
  const ip = imgTriGeom.attributes.position;
  for (let i = 0; i < 3; i++) {
    const po = obsSpheres[i].position;
    const pr = reproject(Pw[i]);
    repSpheres[i].position.copy(pr);
    setCyl(resCyls[i], po, pr);
    const d2 = po.distanceToSquared(pr);
    sse += d2;
    const px = (Math.sqrt(d2) * PX).toFixed(1);
    resLabels[i].div.innerHTML = `r<sub>${NAMES[i]}</sub> = ${px} px`;
    resLabels[i].pos.copy(po).lerp(pr, 0.5);
    resLabels[i].div.style.display = state.mode === 'ind' ? '' : 'none';
    obsLabels[i].pos.copy(po);
    repLabels[i].pos.copy(pr);
    ip.setXYZ(i, po.x, po.y, po.z);
  }
  ip.needsUpdate = true;
  imgTriGeom.computeBoundingSphere();
  setCyl(imgEdges[0], obsSpheres[0].position, obsSpheres[1].position);
  setCyl(imgEdges[1], obsSpheres[1].position, obsSpheres[2].position);
  setCyl(imgEdges[2], obsSpheres[2].position, obsSpheres[0].position);
  const cen = new THREE.Vector3();
  obsSpheres.forEach(s => cen.add(s.position));
  cen.multiplyScalar(1 / 3);
  miniTri.position.copy(cen);
  updateRays();
  if (state.mode === 'tot') {
    ssePanel.style.display = '';
    ssePanel.textContent = `SSE = Σ||pᵢ−p′ᵢ||² = ${(sse * PX * PX).toFixed(0)} px²`;
  } else ssePanel.style.display = 'none';
}

// ---- UI wiring ----
function bindSlider(id, key, fmt) {
  const el = document.getElementById(id);
  const out = document.getElementById(id === 'focalLength' ? 'fVal' : id === 'camYaw' ? 'yawVal' : 'txVal');
  el.addEventListener('input', () => {
    state[key] = parseFloat(el.value);
    out.textContent = fmt(state[key]);
    updateAll();
  });
