Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>focal length f (K) <span id="fVal">1.60</span>
  <input type="range" id="focalLength" min="0.8" max="2.4" step="0.05" value="1.6"></label>
