<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ──────────────────────────────────────────────────────────
// origin tripod      → 3 ArrowHelpers 0x22ff22, length 2.0, big heads (X_L = -X, Y_L = +Y, Z_L = +Z); serif italic labels 20px
// image plane        → PlaneGeometry(3.2, 4.4) at (0.9, 0, 1.5): thick black EdgesGeometry outline + faint white fill
// observed p_i       → SphereGeometry(0.075) + black rim, on plane z=1.5 (p1 red right-middle, p2 cyan bottom apex, p3 green left)
// reprojected p'_i   → SphereGeometry(0.062) + black rim, same colors, offset by perturbed (f, yaw, tx) model
// residuals          → red cylinders r=0.035 between p_i and p'_i + red numeric px labels
// image triangle     → orange BufferGeometry fill + 3 dark edge cylinders r=0.02; small green tripod at centroid
// projection rays    → grey dashed origin→p_i, black dashed p_i→P_i (LineDashedMaterial)
// world points P_i   → SphereGeometry(0.18) + black rim (P1 red upper far right, P2 cyan lower right, P3 green upper left)
// world triangle     → orange BufferGeometry fill + 3 dark edge cylinders r=0.03
const F_TRUE = 1.5, PX = 200, PLANE_CX = 0.9;
const PLANE_W = 3.2, PLANE_H = 4.4;
const COLS = [0xee2211, 0x33bbee, 0x22dd22];
const NAMES = ['1', '2', '3'];
// Start with a SMALL NONZERO calibration error so the red residuals are visible immediately
const state = { f: 1.6, yaw: 0.02, tx: 0.12, mode: 'ind' };

// Observed image points on the plane (upper half, like the source)
const pObs = [
  new THREE.Vector3(PLANE_CX + 0.75, 1.05, F_TRUE),   // p1 red — right-middle
  new THREE.Vector3(PLANE_CX + 0.00, 0.35, F_TRUE),   // p2 cyan — bottom apex
  new THREE.Vector3(PLANE_CX - 0.85, 1.25, F_TRUE)    // p3 green — left
];
const DEPTHS = [4.8, 4.2, 4.5];
const Pw = pObs.map((p, i) => p.clone().multiplyScalar(DEPTHS[i] / F_TRUE));

// ---- camera tripod at origin (large & vivid, matches source) ----
function arrow(dir, len, color, headL = 0.32, headW = 0.17) {
  return new THREE.ArrowHelper(dir.clone().normalize(), new THREE.Vector3(), len, color, headL, headW);
}
scene.add(arrow(new THREE.Vector3(-1, 0, 0), 2.0, 0x22ff22));
scene.add(arrow(new THREE.Vector3(0, 1, 0), 2.0, 0x22ff22));
scene.add(arrow(new THREE.Vector3(0, 0, 1), 2.0, 0x22ff22));

// ---- image plane (large quad, black outline + faint fill) ----
const planeGeom = new THREE.PlaneGeometry(PLANE_W, PLANE_H);
const planeFill = new THREE.Mesh(planeGeom, new THREE.MeshBasicMaterial({
  color: 0xf2f2f2, transparent: true, opacity: 0.22, depthWrite: false, side: THREE.DoubleSide
}));
planeFill.position.set(PLANE_CX, 0, F_TRUE);
scene.add(planeFill);
const planeEdges = new THREE.LineSegments(new THREE.EdgesGeometry(planeGeom),
  new THREE.LineBasicMaterial({ color: 0x111111 }));
planeEdges.position.set(PLANE_CX, 0, F_TRUE + 0.002);
scene.add(planeEdges);

// ---- shared helpers ----
const _up = new THREE.Vector3(0, 1, 0);
function setCyl(c, a, b) {
  const d = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(d.length(), 1e-6);
  c.position.copy(a).addScaledVector(d, 0.5);
  c.scale.set(1, len, 1);
  c.quaternion.setFromUnitVectors(_up, d.normalize());
}
function edgeCyl(a, b, r, color) {
  const c = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 1, 10),
    new THREE.MeshBasicMaterial({ color }));
  setCyl(c, a, b);
  scene.add(c);
  return c;
}
function rimmedSphere(color, r) {
  const s = new THREE.Mesh(new THREE.SphereGeometry(r, 22, 16),
    new THREE.MeshBasicMaterial({ color }));
  const rim = new THREE.Mesh(new THREE.SphereGeometry(r * 1.14, 22, 16),
    new THREE.MeshBasicMaterial({ color: 0x111111, side: THREE.BackSide }));
  s.add(rim);
  scene.add(s);
  return s;
}

// ---- world points ----
const worldSpheres = Pw.map((p, i) => {
  const s = rimmedSphere(COLS[i], 0.18);
  s.position.copy(p);
  return s;
});

// ---- world triangle (orange fill + dark border) ----
const worldEdges = [edgeCyl(Pw[0], Pw[1], 0.03, 0x1a1a1a),
                    edgeCyl(Pw[1], Pw[2], 0.03, 0x1a1a1a),
                    edgeCyl(Pw[2], Pw[0], 0.03, 0x1a1a1a)];
let worldTri = null;
function rebuildWorldTri() {
  if (worldTri) {
    worldTri.geometry.setFromPoints([Pw[0], Pw[1], Pw[2]]);
    worldTri.geometry.setIndex([0, 1, 2]);
    worldTri.geometry.computeVertexNormals();
  } else {
    const g = new THREE.BufferGeometry().setFromPoints([Pw[0], Pw[1], Pw[2]]);
    g.setIndex([0, 1, 2]);
    g.computeVertexNormals();
    worldTri = new THREE.Mesh(g, new THREE.MeshBasicMaterial({
      color: 0xffaa22, side: THREE.DoubleSide, transparent: true, opacity: 0.9
    }));
    scene.add(worldTri);
  }
  setCyl(worldEdges[0], Pw[0], Pw[1]);
  setCyl(worldEdges[1], Pw[1], Pw[2]);
  setCyl(worldEdges[2], Pw[2], Pw[0]);
}
rebuildWorldTri();

// ---- observed points p_i ----
const obsSpheres = pObs.map((p, i) => {
  const s = rimmedSphere(COLS[i], 0.075);
  s.position.copy(p);
  return s;
});

// ---- dashed rays: grey origin→p, black p→P ----
function dashedLine(color) {
  const l = new THREE.Line(new THREE.BufferGeometry(),
    new THREE.LineDashedMaterial({ color, dashSize: 0.18, gapSize: 0.13 }));
  scene.add(l);
  return l;
}
const rayGrey = pObs.map(() => dashedLine(0x999999));
const rayBlack = pObs.map(() => dashedLine(0x111111));
function setDashed(line, a, b) {
  line.geometry.dispose();
  line.geometry = new THREE.BufferGeometry().setFromPoints([a, b]);
  line.computeLineDistances();
}
const ORIGIN = new THREE.Vector3();
function updateRays() {
  for (let i = 0; i < 3; i++) {
    const p = obsSpheres[i].position;
    setDashed(rayGrey[i], ORIGIN, p);
    setDashed(rayBlack[i], p, Pw[i]);
  }
}

// ---- image triangle (orange fill + dark border) ----
const imgTriGeom = new THREE.BufferGeometry();
imgTriGeom.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3));
imgTriGeom.setIndex([0, 1, 2]);
const imgTri = new THREE.Mesh(imgTriGeom, new THREE.MeshBasicMaterial({
  color: 0xffaa22, side: THREE.DoubleSide, transparent: true, opacity: 0.95
}));
scene.add(imgTri);
const imgEdges = [edgeCyl(pObs[0], pObs[1], 0.02, 0x1a1a1a),
                  edgeCyl(pObs[1], pObs[2], 0.02, 0x1a1a1a),
                  edgeCyl(pObs[2], pObs[0], 0.02, 0x1a1a1a)];

// ---- reprojected points p'_i + red residual cylinders ----
const repSpheres = pObs.map((p, i) => {
  const s = rimmedSphere(COLS[i], 0.062);
  s.position.copy(p);
  return s;
});
const resCyls = pObs.map((p, i) => edgeCyl(p, p.clone().add(new THREE.Vector3(0.1, 0.1, 0)), 0.035, 0xdd0000));

// ---- mini green tripod at image-triangle centroid ----
const miniTri = new THREE.Group();
miniTri.add(arrow(new THREE.Vector3(1, 0, 0), 0.45, 0x22ff22, 0.12, 0.08));
miniTri.add(arrow(new THREE.Vector3(0, 1, 0), 0.45, 0x22ff22, 0.12, 0.08));
miniTri.add(arrow(new THREE.Vector3(0.55, 0.3, 0.5), 0.45, 0x22ff22, 0.12, 0.08));
scene.add(miniTri);

// ---- reprojection model: yaw about Y, +tx on X, project with estimated f ----
function reproject(pt) {
  const c = Math.cos(state.yaw), s = Math.sin(state.yaw);
  const x = pt.x * c + pt.z * s + state.tx;
  const z = -pt.x * s + pt.z * c;
  return new THREE.Vector3(state.f * x / z, state.f * pt.y / z, F_TRUE);
}

// ---- camera view: plane left-of-center, world triangle receding upper-right ----
setCameraView({
  projection: 'perspective', azimuthDeg: 125, elevationDeg: 20, rollDeg: 0,
  heightFraction: 0.72, target: [1.6, 0.4, 2.2], distanceScale: 1.1
});

// ---- labels (large, bold, serif — matching the source's prominent labeling) ----
const SERIF = 'font-family:Georgia,\'Times New Roman\',serif;';
const pWorldLabels = Pw.map((p, i) =>
  addLabel(`<span style="${SERIF}"><i><b>P</b></i><sub>${NAMES[i]}</sub></span>`, p,
    { offset: [[36, -12], [32, 22], [-16, -30]][i], fontSize: '22px' }));
addLabel(`<span style="${SERIF}"><i>X</i><sub>L</sub></span>`, new THREE.Vector3(-2.15, 0, 0), { offset: [-8, 16], fontSize: '20px' });
addLabel(`<span style="${SERIF}"><i>Y</i><sub>L</sub></span>`, new THREE.Vector3(0, 2.15, 0), { offset: [-16, -8], fontSize: '20px' });
addLabel(`<span style="${SERIF}"><i>Z</i><sub>L</sub></span>`, new THREE.Vector3(0, 0, 2.15), { offset: [16, 16], fontSize: '20px' });
const obsLabels = pObs.map((p, i) =>
  addLabel(`<span style="${SERIF}"><i><b>p</b></i><sub>${NAMES[i]}</sub></span>`, p,
    { offset: [[28, 16], [-4, 28], [-28, 14]][i], fontSize: '18px' }));
const repLabels = pObs.map((p, i) =>
  addLabel(`<span style="${SERIF}"><i><b>p</b></i>&prime;<sub>${NAMES[i]}</sub></span>`, p,
    { offset: [[26, -20], [32, 18], [-24, -26]][i], fontSize: '17px' }));
const resLabels = pObs.map(p =>
  addLabel('', p, { offset: [0, -20], fontSize: '13px', color: '#cc0000', background: 'rgba(255,255,255,0.88)' }));

// ---- reactive update ----
const ssePanel = document.getElementById('ssePanel');
function updateAll() {
  let sse = 0;
  const ip = imgTriGeom.attributes.position;
  for (let i = 0; i < 3; i++) {
    const po = obsSpheres[i].position;
    const pr = reproject(Pw[i]);
    repSpheres[i].position.copy(pr);
    setCyl(resCyls[i], po, pr);
    const d2 = po.distanceToSquared(pr);
    sse += d2;
    resLabels[i].div.innerHTML = `r<sub>${NAMES[i]}</sub> = ${(Math.sqrt(d2) * PX).toFixed(1)} px`;
    resLabels[i].pos.copy(po).lerp(pr, 0.5);
    resLabels[i].div.style.display = state.mode === 'ind' ? '' : 'none';
    obsLabels[i].pos.copy(po);
    repLabels[i].pos.copy(pr);
    pWorldLabels[i].pos.copy(Pw[i]);
    ip.setXYZ(i, po.x, po.y, po.z);
  }
  ip.needsUpdate = true;
  imgTriGeom.computeBoundingSphere();
  setCyl(imgEdges[0], obsSpheres[0].position, obsSpheres[1].position);
  setCyl(imgEdges[1], obsSpheres[1].position, obsSpheres[2].position);
  setCyl(imgEdges[2], obsSpheres[2].position, obsSpheres[0].position);
  const cen = new THREE.Vector3();
  obsSpheres.forEach(s => cen.add(s.position));
  cen.multiplyScalar(1 / 3);
  miniTri.position.copy(cen);
  updateRays();
  if (state.mode === 'tot') {
    ssePanel.style.display = '';
    ssePanel.textContent = `SSE = Σ||pᵢ−p′ᵢ||² = ${(sse * PX * PX).toFixed(0)} px²`;
  } else ssePanel.style.display = 'none';
}

// ---- UI wiring ----
function bindSlider(id, key, fmt, outId) {
  const el = document.getElementById(id);
  const out = document.getElementById(outId);
  el.addEventListener('input', () => {
    state[key] = parseFloat(el.value);
    out.textContent = fmt(state[key]);
    updateAll();
  });
  return el;
}
const elF = bindSlider('focalLength', 'f', v => v.toFixed(2), 'fVal');
const elY = bindSlider('camYaw', 'yaw', v => v.toFixed(2), 'yawVal');
const elT = bindSlider('camTransX', 'tx', v => v.toFixed(2), 'txVal');
const bInd = document.getElementById('modeInd'), bTot = document.getElementById('modeTot');
function setMode(m) {
  state.mode = m;
  bInd.classList.toggle('active', m === 'ind');
  bTot.classList.toggle('active', m === 'tot');
  updateAll();
}
bInd.addEventListener('click', () => setMode('ind'));
bTot.addEventListener('click', () => setMode('tot'));

// ---- demo steps ----
const STEPS = [
  { title: 'Small calibration error', f: 1.6, yaw: 0.02, tx: 0.12, mode: 'ind',
    text: 'Near-true parameters: p′ sit close to p and the three red residual segments are short — each is the 2D error the optimizer sees for that point.' },
  { title: 'Wrong focal length', f: 2.1, yaw: 0, tx: 0, mode: 'ind',
    text: 'Larger f pushes all reprojections radially outward from the image center — a coherent pattern betraying an intrinsic error.' },
  { title: 'Wrong pose', f: 1.5, yaw: 0.25, tx: -0.8, mode: 'ind',
    text: 'Yaw + translation distort the reprojected triangle; residuals differ per point because pose errors interact with scene depth.' },
  { title: 'The optimization objective', f: 1.5, yaw: 0.25, tx: -0.8, mode: 'tot',
    text: 'The three residuals collapse into one number — the sum of squared lengths — exactly the objective nonlinear calibration minimizes over K, R, T.' }
];
const narr = document.getElementById('stepNarration');
function goToStep(i) {
  const s = STEPS[i];
  elF.value = s.f; elY.value = s.yaw; elT.value = s.tx;
  state.f = s.f; state.yaw = s.yaw; state.tx = s.tx;
  document.getElementById('fVal').textContent = s.f.toFixed(2);
  document.getElementById('yawVal').textContent = s.yaw.toFixed(2);
  document.getElementById('txVal').textContent = s.tx.toFixed(2);
  setMode(s.mode);
  narr.textContent = s.title + ': ' + s.text;
  document.querySelectorAll('.stepBtn').forEach(b =>
    b.classList.toggle('active', +b.dataset.step === i));
}
document.querySelectorAll('.stepBtn').forEach(b =>
  b.addEventListener('click', () => goToStep(+b.dataset.step)));

// ---- dragging observed / reprojected points on the image plane ----
const dragRay = new THREE.Raycaster();
const dragPtr = new THREE.Vector2();
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), -F_TRUE);
let dragObj = null, dragIsObs = false, dragIdx = -1;
canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPtr.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRay.setFromCamera(dragPtr, camera);
  const targets = [];
  obsSpheres.forEach((s, i) => targets.push({ s, i, obs: true }));
  repSpheres.forEach((s, i) => targets.push({ s, i, obs: false }));
  const hits = dragRay.intersectObjects(targets.map(t => t.s), false);
  if (hits.length) {
    const t = targets.find(t => t.s === hits[0].object);
    dragObj = t.s; dragIsObs = t.obs; dragIdx = t.i;
    controls.enabled = false;
  }
});
window.addEventListener('pointermove', (e) => {
  if (!dragObj) return;
  const rect = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPtr.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRay.setFromCamera(dragPtr, camera);
  const hit = new THREE.Vector3();
  if (dragRay.ray.intersectPlane(dragPlane, hit)) {
    hit.x = THREE.MathUtils.clamp(hit.x, PLANE_CX - 1.5, PLANE_CX + 1.5);
    hit.y = THREE.MathUtils.clamp(hit.y, -2.1, 2.1);
    hit.z = F_TRUE;
    if (dragIsObs) {
      // slide the observed point along its ray: re-extend origin → p_i → P_i
      obsSpheres[dragIdx].position.copy(hit);
      const dir = hit.clone().normalize();
      Pw[dragIdx].copy(dir.multiplyScalar(Pw[dragIdx].length()));
      worldSpheres[dragIdx].position.copy(Pw[dragIdx]);
      rebuildWorldTri();
      updateAll();
    } else {
      repSpheres[dragIdx].position.copy(hit);
      setCyl(resCyls[dragIdx], obsSpheres[dragIdx].position, hit);
      repLabels[dragIdx].pos.copy(hit);
      const dd = obsSpheres[dragIdx].position.distanceTo(hit);
      resLabels[dragIdx].div.innerHTML = `r<sub>${NAMES[dragIdx]}</sub> = ${(dd * PX).toFixed(1)} px`;
      resLabels[dragIdx].pos.copy(obsSpheres[dragIdx].position).lerp(hit, 0.5);
    }
  }
});
window.addEventListener('pointerup', () => {
  if (dragObj) { dragObj = null; controls.enabled = true; }
});

// ---- hover/click explainers ----
registerInteractive(planeFill, {
  title: 'Image plane',
